Implement synthesizeGrounded(query, outcome, llm, footer, opts?) in literature.ts (keep it next to synthesize so it shares helpers). Algorithm:
  if (outcome.kind !== 'grounded') return synthesize(query, outcome, llm, footer); // disabled/abstain already handled there
  let answer; try { answer = await synthesize(query, outcome, llm, footer); } catch { return abstainAnswer(footer); }
  if (answer.abstained) return answer; // synthesize itself abstained (empty/ABSTAIN/no passages)
  let verdict; try { verdict = await getGroundingVerdict({ llm, model: SYNTHESIS_MODEL, question: query, answerBody: answer.body, passages: outcome.passages }); } catch { return abstainAnswer(footer); }
  if (verdict.verdict === 'approve') return answer;
  // one re-synthesis with feedback
  let answer2; try { answer2 = await synthesizeWithFeedback(query, outcome, llm, footer, verdict.feedback); } catch { return abstainAnswer(footer); }
  if (answer2.abstained) return answer2;
  let verdict2; try { verdict2 = await getGroundingVerdict({ ... answerBody: answer2.body, passages: outcome.passages }); } catch { return abstainAnswer(footer); }
  return verdict2.verdict === 'approve' ? answer2 : abstainAnswer(footer);
 where abstainAnswer(footer) returns { body: 'I cannot provide a sufficiently-supported answer grounded in the retrieved literature. For evidence-based guidance, please consult a licensed healthcare professional.', abstained:true, citations:[], disclaimerFooter:footer, shortCircuit:false } and synthesizeWithFeedback is synthesize with one extra system-prompt line: `Address this reviewer feedback while staying grounded ONLY in the passages: ${feedback}`. Export const GROUNDED_GATE_MAX_LLM_CALLS = 2 /*synth*/ + 2*GROUNDING_MAX_LLM_CALLS? — set it to the actual worst case: 1 (synth) + GROUNDING_MAX_LLM_CALLS (critic) + 1 (re-synth) + GROUNDING_MAX_LLM_CALLS (re-critic); compute from the imported constant, not a literal.

